ALTER TABLE employer_accounts ADD COLUMN IF NOT EXISTS subscription_required BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE employer_accounts ALTER COLUMN subscription_required SET DEFAULT TRUE;
CREATE TABLE IF NOT EXISTS company_subscriptions(employer_id UUID PRIMARY KEY REFERENCES employer_accounts(id),plan TEXT NOT NULL CHECK(plan IN ('basic','professional','business','enterprise')),status TEXT NOT NULL CHECK(status IN ('active','expired')),currency TEXT NOT NULL,paid_until TIMESTAMPTZ NOT NULL,reference TEXT NOT NULL UNIQUE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS company_payment_orders(reference TEXT PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id),plan TEXT NOT NULL,country TEXT NOT NULL,currency TEXT NOT NULL,amount_minor BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',provider_mode TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_exits(id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id),employee_id UUID NOT NULL REFERENCES workforce_employees(id),reason TEXT NOT NULL CHECK(reason IN ('resignation','termination','retirement','contract_end')),effective_date DATE NOT NULL,notes TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('scheduled','completed')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE workforce_employees ALTER COLUMN employee_number SET DEFAULT ('AT-'||UPPER(SUBSTR(REPLACE(gen_random_uuid()::text,'-',''),1,12)));
UPDATE workforce_employees SET employee_number='AT-'||UPPER(SUBSTR(REPLACE(id::text,'-',''),1,12)) WHERE employee_number IS NULL OR BTRIM(employee_number)='';
CREATE TABLE IF NOT EXISTS personal_support_tickets(id UUID PRIMARY KEY,requester_role TEXT NOT NULL,requester_id UUID NOT NULL,employer_id UUID REFERENCES employer_accounts(id),title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',reply TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE workflow_alerts ADD COLUMN IF NOT EXISTS read_at TIMESTAMPTZ;
